lemmas.split₂ˡ:
{X₁ = A : Obj} {Y₁ = B : Obj} {X₂ = x : Obj} {Y₂ = y : Obj}
{Z₂ = Z₃ : Obj}
{f = f₁ : A ⇒ B} {g = g₁ : y ⇒ Z₃} {h = h₁ : x ⇒ y} →
f₁ ⊗₁ (g₁ ∘ h₁) ≈ id ⊗₁ g₁ ∘ f₁ ⊗₁ h₁

lemmas.⊗-interchange:
{A B : Obj} {C = x : Obj} {D = y : Obj} {E = Z₃ : Obj}
{F = f₁ : Obj}
{a = g₁ : A ⇒ B} {b = h₁ : B ⇒ x} {c : y ⇒ Z₃} {d : Z₃ ⇒ f₁} →
(h₁ ∘ g₁) ⊗₁ (d ∘ c) ≈ h₁ ⊗₁ d ∘ g₁ ⊗₁ c

lemma_normal.split₂ˡ:
{X₁ = A : Obj} {Y₁ = B : Obj} {X₂ = x : Obj} {Y₂ = y : Obj}
{Z₂ = Z₃ : Obj}
{f = f₁ : A ⇒ B} {g = g₁ : y ⇒ Z₃} {h = h₁ : x ⇒ y} →
⊗.F₁ (f₁ , g₁ ∘ h₁) ≈ ⊗.F₁ (id , g₁) ∘ ⊗.F₁ (f₁ , h₁)

lemma_normal.⊗-interchange:
{A B : Obj} {C = x : Obj} {D = y : Obj} {E = Z₃ : Obj}
{F = f₁ : Obj}
{a = g₁ : A ⇒ B} {b = h₁ : B ⇒ x} {c : y ⇒ Z₃} {d : Z₃ ⇒ f₁} →
⊗.F₁ (h₁ ∘ g₁ , d ∘ c) ≈ ⊗.F₁ (h₁ , d) ∘ ⊗.F₁ (g₁ , c)

